int get_bitmap_file(struct mddev *mddev, void __user *arg)
{
    struct {
        char pathname[NAME_MAX + 1];
    } *bitmap_file;
    int ret = -ENOMEM;

    bitmap_file = kmalloc(sizeof(*bitmap_file), GFP_KERNEL);
    if (!bitmap_file)
        goto out;

    bitmap_file->pathname[0] = '\0';

    if (mddev->bitmap && mddev->bitmap->file) {
        char *src_path = file_path(mddev->bitmap->file, bitmap_file->pathname, NAME_MAX + 1);
        if (IS_ERR(src_path)) {
            ret = PTR_ERR(src_path);
            goto out_free;
        }
    }

    if (copy_to_user(arg, bitmap_file, sizeof(*bitmap_file))) {
        ret = -EFAULT;
        goto out_free;
    }

    ret = 0;

out_free:
    kfree(bitmap_file);
out:
    return ret;
}
